using UnityEngine;

[Serializable]
public class GameData
{
	public enum Stat
	{
		Death = 0,
		Gold = 1,
		Spike = 2,
		Fall = 3,
		Damage = 5,
		Destructible = 6,
		Plat = 7,
		Painting = 8
	}

	[Serializable]
	public class GameStats
	{
		public float totalPlayTime;

		private int tempStatVal;

		private int tempValue;

		private Dictionary<int, int> intStatsDictionary;

		public Dictionary<string, int> enemiesDefeatedDictionary;

		public GameStats()
		{
			Reset();
		}

		public void UpdatePlayTime()
		{
			totalPlayTime += GameController.timeSinceLastTimeSave;
			GameController.timeSinceLastTimeSave = 0f;
		}

		public int GetIntStatValue(Stat givenStat)
		{
			return (!intStatsDictionary.ContainsKey((int)givenStat)) ? (-1) : intStatsDictionary[(int)givenStat];
		}

		public void UpdateIntStatValue(Stat givenStat, int givenAmount = 1)
		{
			if (Globals.InGameScene(string.Empty) && givenAmount >= 1)
			{
				tempStatVal = (int)givenStat;
				if (!intStatsDictionary.ContainsKey(tempStatVal))
				{
					intStatsDictionary.Add(tempStatVal, 0);
				}
				tempValue = intStatsDictionary[tempStatVal];
				intStatsDictionary[tempStatVal] = Mathf.Min(99999999, tempValue + givenAmount);
			}
		}

		public void EnemyDefeated(string name)
		{
			if (!enemiesDefeatedDictionary.ContainsKey(name))
			{
				enemiesDefeatedDictionary.Add(name, 0);
			}
			enemiesDefeatedDictionary[name]++;
		}

		public int GetEnemyDefeatedCount(string givenName)
		{
			return enemiesDefeatedDictionary.ContainsKey(givenName) ? enemiesDefeatedDictionary[givenName] : 0;
		}

		public void Reset()
		{
			totalPlayTime = 0f;
			InitEnemiesDefeatedDictionary();
			InitIntStatsDictionary();
		}

		private void InitEnemiesDefeatedDictionary()
		{
			if (enemiesDefeatedDictionary == null)
			{
				enemiesDefeatedDictionary = new Dictionary<string, int>();
			}
			enemiesDefeatedDictionary.Clear();
		}

		private void InitIntStatsDictionary()
		{
			if (intStatsDictionary == null)
			{
				intStatsDictionary = new Dictionary<int, int>();
			}
			intStatsDictionary.Clear();
			intStatsDictionary.Add(1, 0);
			intStatsDictionary.Add(7, 0);
			intStatsDictionary.Add(0, 0);
			intStatsDictionary.Add(2, 0);
			intStatsDictionary.Add(3, 0);
			intStatsDictionary.Add(5, 0);
			intStatsDictionary.Add(6, 0);
			intStatsDictionary.Add(8, 0);
		}
	}

