	public void SavePlayerData()
	{
		for (int i = 0; i < GameController.activePlayers.Length; i++)
		{
			Player player = GameController.activePlayers[i];
			if (player == null)
			{
				continue;
			}
			if (playerData[i] == null)
			{
				playerData[i] = new PlayerData();
			}
			playerData[i].outfitName = player.outfitID;
			int num = 4;
			int num2 = 3;
			bool[] array = new bool[num];
			int[] array2 = new int[num];
			string[] array3 = new string[num];
			for (int j = 0; j < num; j++)
			{
				Player.SkillState skillState = null;
				switch (j)
				{
				case 0:
					skillState = player.GetBasicSkill();
					break;
				case 1:
					skillState = player.GetDashSkill();
					break;
				case 2:
					skillState = player.GetAnyStandardSkill();
					break;
				case 3:
					skillState = player.GetSignatureSkill();
					break;
				}
				array[j] = skillState != null;
				if (array[j])
				{
					array2[j] = skillState.SetSkillSlot();
					array3[j] = skillState.skillID;
					continue;
				}
				switch (j)
				{
				case 0:
					array3[j] = Player.WindSlashBasic.staticID;
					break;
				case 1:
					array3[j] = Player.DashState.staticID;
					break;
				case 2:
					array3[j] = Player.ShootFireArc.staticID;
					break;
				case 3:
					array3[j] = Player.ShootFireball.staticID;
					break;
				}
			}
			for (int k = 0; k < playerData[i].skills.Length; k++)
			{
				playerData[i].skills[k] = string.Empty;
			}
			for (int l = 0; l < num; l++)
			{
				if (array[l])
				{
					playerData[i].skills[array2[l]] = array3[l];
					if (l == num2)
					{
						playerData[i].signatureSkillIndex = array2[l];
					}
				}
			}
			for (int m = 0; m < num; m++)
			{
				if (array[m])
				{
					continue;
				}
				for (int n = 0; n < playerData[i].skills.Length; n++)
				{
					if (playerData[i].skills[n] == string.Empty)
					{
						playerData[i].skills[n] = array3[m];
						if (m == num2)
						{
							playerData[i].signatureSkillIndex = n;
						}
						break;
					}
				}
			}
			playerData[i].designatedItemName = player.designatedItemID;
			if (playerData[i].designatedItemName == null || playerData[i].designatedItemName == string.Empty)
			{
				playerData[i].designatedItemName = "Default";
			}
		}
	}

