	{
		outfitDataDictionary = new Dictionary<string, bool>();
		foreach (string key in Outfit.OutfitDict.Keys)
		{
			outfitDataDictionary.Add(key, value: false);
		}
		outfitDataDictionary["Hope"] = true;
		outfitDataDictionary["Patience"] = true;
		PullOutfitData();
	}

	public void PushSkillData()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			foreach (Player.SkillState value in player.skillsDict.Values)
			{
				if (value != null)
				{
					if (!skillDataDictionary.ContainsKey(value.skillID))
					{
						skillDataDictionary.Add(value.skillID, new StoredSkillData());
					}
					if (!skillDataDictionary[value.skillID].isUnlocked)
					{
						skillDataDictionary[value.skillID].isUnlocked = value.isUnlocked;
					}
					if (!skillDataDictionary[value.skillID].signatureUnlocked)
					{
						skillDataDictionary[value.skillID].signatureUnlocked = value.signatureUnlocked;
					}
				}
			}
		}
	}

	public void PullSkillData()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			foreach (KeyValuePair<string, StoredSkillData> item in skillDataDictionary)
			{
				if (player.skillsDict.ContainsKey(item.Key) && player.skillsDict[item.Key] != null)
				{
					player.skillsDict[item.Key].isUnlocked = item.Value.isUnlocked;
					player.skillsDict[item.Key].signatureUnlocked = item.Value.signatureUnlocked;
				}
			}
		}
	}

	public void ResetSkillData()
	{
		elementUsage.Clear();
		foreach (StoredSkillData value in skillDataDictionary.Values)
		{
			value.Reset();
		}
		foreach (string startingSkillID in Globals.startingSkillIDList)
		{
			if (!skillDataDictionary.ContainsKey(startingSkillID))
			{
				skillDataDictionary[startingSkillID] = new StoredSkillData();
			}
			skillDataDictionary[startingSkillID].isUnlocked = true;
		}
		foreach (string startingOverdriveID in Globals.startingOverdriveIDList)
		{
			if (!skillDataDictionary.ContainsKey(startingOverdriveID))
			{
				skillDataDictionary[startingOverdriveID] = new StoredSkillData();
			}
			skillDataDictionary[startingOverdriveID].isUnlocked = true;
			skillDataDictionary[startingOverdriveID].signatureUnlocked = true;
		}
		if (GameController.playerScripts != null)
		{
			PullSkillData();
		}
	}

	public bool CheckSkillDataEntry(string givenID, bool signature = false)
	{
		if (!skillDataDictionary.ContainsKey(givenID))
		{
			skillDataDictionary[givenID] = new StoredSkillData();
		}
		return (!signature) ? skillDataDictionary[givenID].isUnlocked : skillDataDictionary[givenID].signatureUnlocked;
	}

	public void UpdateSkillDataEntry(string skillID, ElementType element, int useCountIncrement = 0, bool overdrive = false)
	{
		if (!(Application.loadedLevelName == "PlayerRoom") && !(Application.loadedLevelName == "Hub") && !Application.loadedLevelName.Contains("PvP") && useCountIncrement > 0)
		{
			if (!skillDataDictionary.ContainsKey(skillID))
			{
				skillDataDictionary.Add(skillID, new StoredSkillData());
			}
			skillDataDictionary[skillID].useCount += useCountIncrement;
			if (overdrive)
			{
				skillDataDictionary[skillID].overdriveCount += useCountIncrement;
			}
			if (!elementUsage.ContainsKey(element))
			{
				elementUsage.Add(element, 0);
			}
			elementUsage[element] += useCountIncrement;
		}
	}

	public bool CheckItemDataEntry(string givenItemID)
	{
		if (!ItemDataDict.ContainsKey(givenItemID))
		{
			ItemDataDict.Add(givenItemID, new StoredItemData());
		}
		return ItemDataDict[givenItemID].isUnlocked;
	}

	public void UpdateItemDataEntry(string givenItemID, bool status = true)
	{
		if (!ItemDataDict.ContainsKey(givenItemID))
		{
			ItemDataDict.Add(givenItemID, new StoredItemData());
		}
		ItemDataDict[givenItemID].isUnlocked = status;
	}

	public void ResetItemData()
	{
		foreach (StoredItemData value in ItemDataDict.Values)
		{
			value.Reset();
		}
		UpdateItemDataEntry(PlayerStartItem.staticID);
		UpdateItemDataEntry(BuffWithFriendship.staticID);
		UpdateItemDataEntry(WaterChargeFamiliarItem.staticID);
	}

	public int GetUnlockedChaosCountCount()
	{
		int num = 0;
		foreach (KeyValuePair<string, StoredSkillData> item in skillDataDictionary)
		{
			if (item.Value != null && item.Value.isUnlocked && LootManager.chaosSkillList.Contains(item.Key))
			{
				num++;
			}
		}
		return num;
	}

	public int GetUnlockedSkillCount(bool signaturesOnly = false)
	{
		int num = 0;
		foreach (StoredSkillData value in skillDataDictionary.Values)
		{
			if (value != null && value.isUnlocked && (!signaturesOnly || value.signatureUnlocked))
			{
				num++;
			}
		}
		return num;
	}

	public int GetUnlockedItemCount()
	{
		int num = 0;
		foreach (StoredItemData value in ItemDataDict.Values)
		{
			if (value.isUnlocked)
			{
				num++;
			}
		}
		return num;
	}

	public int GetUnlockedOutfitCount()
	{
		int num = 0;
		foreach (bool value in outfitDataDictionary.Values)
		{
			if (value)
			{
				num++;
			}
		}
		return num;
	}

	public bool IsValid()
	{
		return playerData != null && skillDataDictionary != null && elementUsage != null && platinumWallet != null && npcDataDictionary != null && outfitDataDictionary != null && gameStats != null && gameStats.enemiesDefeatedDictionary != null;
	}

	public void PrintData()
	{
		string text = "** Game Data **";
		text += "\n\nElement Use Data:";
		foreach (KeyValuePair<ElementType, int> item in elementUsage)
		{
			string text2 = text;
			text = text2 + "\n  " + item.Key.ToString() + " element spells used: " + item.Value;
		}
		text += "\n\nSpells Unlocked:";
