		text = text + "\n  Total Gold Collected: " + gameStats.GetIntStatValue(Stat.Gold);
		text = text + "\n  Total Plat Collected: " + gameStats.GetIntStatValue(Stat.Plat);
		text = text + "\n  Total Destructibles Destroyed: " + gameStats.GetIntStatValue(Stat.Destructible);
		text = text + "\n  Total Paintings Destroyed: " + gameStats.GetIntStatValue(Stat.Painting);
		text = text + "\n  Total Spikes Stepped On: " + gameStats.GetIntStatValue(Stat.Spike);
