	public void Activate(string nextLevel)
	{
		if (GameUI.pauseMenu != null && GameUI.pauseMenu.paused)
		{
			GameUI.TogglePause();
		}
		TimeScaleController.Pause(status: true);
		nextLevelName = nextLevel;
		SetValues(GameController.levelTime, Minimap.RevealedPercentage, GameController.levelGold, GameController.levelPlat);
		activated = true;
		gameObject.SetActive(value: true);
		GameController.PauseAllPlayers();
		continueImage.sprite = GameUI.GetInputSprite(GameController.activePlayers[0].inputDevice.inputScheme);
		if (Application.loadedLevelName.Contains("Boss"))
		{
			anim.Play("IdleLevel4");
			return;
		}
		switch (GameController.stageCount)
		{
		case 1:
			anim.Play("Level1To2");
			break;
		case 2:
			anim.Play("Level2To3");
			break;
		case 3:
			anim.Play("Level3To4");
			break;
		default:
			anim.Play("Idle");
			break;
		}
	}
