		case 2:
			anim.Play("IdleLevel3");
			break;
		case 3:
			anim.Play("IdleLevel4");
			break;
		default:
			anim.Play("Idle");
			break;
		}
	}
	protected override void Update()
	{
		base.Update();
		if (!activated)
		{
			return;
		}
		if (!frameSkipped)
		{
			frameSkipped = true;
			return;
		}
		if (buttonDelayTimer > 0f)
		{
			buttonDelayTimer -= deltaTime;
		}
		else if (InputController.GetAnyDeviceButtonUp("Confirm") != null)
		{
			Deactivate();
			buttonDelayTimer = buttonDelay;
		}
		if (!GameController.coopOn || GameController.activePlayers.Length != 2 || crownAnimPlayed)
		{
			return;
		}
		if (crownDelayTimer > 0f)
		{
			crownDelayTimer -= deltaTime;
			return;
		}
		if (player1Wins == 1)
		{
			playerStatRefs[0].crownAnim.Play("CrownSpawn");
		}
		else if (player1Wins == -1)
		{
			playerStatRefs[1].crownAnim.Play("CrownSpawn");
		}
		else
		{
			playerStatRefs[0].crownAnim.Play("CrownSpawn");
			playerStatRefs[1].crownAnim.Play("CrownSpawn");
		}
		crownAnimPlayed = true;
	}
	private void Deactivate()
	{
		TimeScaleController.Pause(status: false);
		Reset();
		GameController.LoadLevel(nextLevelName);
	}
	private void DetermineWinner(int winnerValue)
	{
		switch (winnerValue)
		{
		case 1:
