	public new class DeadState : State<Player>
	{
		private GameObject ghostPrefab;

		private GameObject currentGhost;

		private ChaosQuickStopwatch resurrectStopwatch = new ChaosQuickStopwatch(1.5f);

		private ResurrectItem currentResItem;

		private bool resAvailable;

		private bool resQueued;

		private bool deathSummaryQueued;

		private bool deathSummaryActivated;

		private int deathSummaryStopwatchID;

		private float deathSummaryDelay = 1f;

		private bool kneesHitFloor;

		private bool bodyHitFloor;

		public DeadState(string stateName, FSM parentFSM, Player parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			ghostPrefab = ChaosBundle.Get("Assets/Prefabs/Player/Ghost.prefab");
			currentGhost = null;
		}

		public override void OnEnter()
		{
			if (parent.fall.CheckOnPit())
			{
				fsm.ChangeState("Fall");
				return;
			}
			parent.facingDirection = FacingDirection.Right;
			parent.isFacingRight = true;
			parent.anim.PlayDirectional("DeadDown");
			GameController.players.Remove(parent.gameObject);
			GameController.allies.Remove(parent.gameObject);
			parent.hud.ToggleBars(enable: false);
			deathSummaryQueued = false;
			deathSummaryActivated = false;
			kneesHitFloor = false;
			bodyHitFloor = false;
			parent.hurtBoxCollider.enabled = false;
			parent.floorCollider.enabled = false;
			if (Application.loadedLevelName.Contains("PvP") || GameController.pvpOn)
			{
				return;
			}
			TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
			currentResItem = parent.inventory.GetResurrectItem();
			resAvailable = currentResItem != null;
			if (resAvailable)
			{
				resQueued = false;
				resurrectStopwatch.IsRunning = true;
				return;
			}
			if (GameController.AllPlayersDead())
			{
				SoundManager.BGMPaused = true;
				deathSummaryQueued = true;
				deathSummaryStopwatchID = ChaosStopwatch.Begin(deathSummaryDelay);
			}
			else if (parent.spawnGhostOnDeath && currentGhost == null)
			{
				Ghost component = UnityEngine.Object.Instantiate(ghostPrefab, parent.transform.position, Quaternion.identity).GetComponent<Ghost>();
				currentGhost = component.gameObject;
				component.parentPlayer = parent;
				component.inputDevice = parent.inputDevice;
			}
			GameDataManager.gameData.UpdateIntStat(GameData.Stat.Death);
			GameDataManager.Save();
		}

		public override void Update()
		{
			if (!kneesHitFloor && parent.anim.AnimPlayed(0.33f))
			{
				kneesHitFloor = true;
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 10;
				float scale = 0.25f;
				float startSpeed = 3f;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitCircle(particleCount, scale, startSpeed, -1f, emitPosition);
			}
			if (!bodyHitFloor && parent.anim.AnimPlayed(0.94f))
			{
				bodyHitFloor = true;
				DustEmitter poolItem2 = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 10;
				float startSpeed = 0.25f;
				float scale = 3f;
				Vector3? emitPosition = parent.transform.position;
				poolItem2.EmitCircle(particleCount, startSpeed, scale, -1f, emitPosition);
			}
			if (resAvailable)
			{
				HandleResurrect();
			}
			else if (deathSummaryQueued && !deathSummaryActivated && ChaosStopwatch.Check(deathSummaryStopwatchID))
			{
				deathSummaryActivated = true;
				GameController.pauseTimer = true;
				GameUI.deathSummary.Activate();
				if (!Level.isBossRushMode && GameController.loopCount > 0)
				{
					RunHistoryEntry.Save();
				}
			}
		}

		public override void OnExit()
		{
			if (parent.deathMenu != null)
			{
				parent.deathMenu.SetActive(value: false);
			}
			parent.hurtBoxCollider.enabled = true;
			parent.floorCollider.enabled = true;
		}

		private void HandleResurrect()
		{
			if (resurrectStopwatch.IsRunning)
			{
				return;
			}
			if (resQueued)
			{
				if (parent.anim.AnimPlayed())
				{
					currentResItem.ResurrectPlayer();
				}
				return;
			}
			parent.overheadPrompt.DisplayPrompt("Confirm", loop: true);
			if (parent.inputDevice.GetButtonDown("Confirm"))
			{
				resQueued = true;
				parent.overheadPrompt.HidePrompt(string.Empty);
				parent.anim.Play("GetUp", -1, 0f);
				SoundManager.PlayAudio("Resurrect");
			}
		}
	}

	public class PlayerFallState : FallState
	{
		public new Player parent;

		private bool playerAlive;

		private bool damageTaken;

		private Vector2 otherPlayerPos;

		private float fallDelay = 1f;

		private new int fallDelayStopwatchID;

		private AttackInfo fallAtkInfo;

		private Vector2 respawnLoc;

		public PlayerFallState(string stateName, FSM parentFSM, Player parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			parent = parentEntity;
			fallAtkInfo = new AttackInfo();
			fallAtkInfo.skillID = "Pit";
			fallAtkInfo.damage = 0;
			fallAtkInfo.canHitStun = false;
			fallAtkInfo.critHitChance = 0f;
			fallAtkInfo.isStatusEffect = true;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			otherPlayerPos = Vector2.zero;
			playerAlive = true;
			damageTaken = false;
			parent.anim.PlayDirectional("Hurt" + ((!parent.multiAnimHurt) ? string.Empty : parent.facingDirection.ToString()));
			GameDataManager.gameData.gameStats.UpdateIntStatValue(GameData.Stat.Fall);
			parent.hurtBoxCollider.enabled = false;
			GameController.allies.Remove(parent.gameObject);
		}

		public override void Update()
		{
			base.Update();
			if (!finishedFalling)
			{
				return;
			}
			if (!damageTaken)
			{
				damageTaken = true;
				playerAlive = TakeFallDamage();
				fallDelayStopwatchID = ChaosStopwatch.Begin(fallDelay);
			}
			if (!ChaosStopwatch.Check(fallDelayStopwatchID) && playerAlive)
			{
				return;
			}
			if (GameController.coopOn && !GameController.pvpOn && !Application.loadedLevelName.Contains("PvP"))
			{
				Player[] activePlayers = GameController.activePlayers;
				foreach (Player player in activePlayers)
				{
					if (player.playerID != parent.playerID && !player.fsm.currentStateName.Contains("Dead") && !player.fsm.currentStateName.Contains("Fall"))
					{
						otherPlayerPos = player.transform.position;
					}
				}
			}
			if (otherPlayerPos != Vector2.zero && Globals.CheckCircle(otherPlayerPos, 0.25f, ChaosCollisions.layerPit) && Vector2.Distance(parent.transform.position, otherPlayerPos) >= 10f)
			{
				respawnLoc = otherPlayerPos;
			}
			else
			{
				respawnLoc = Entity.GetAvailableNearbyLocation(parent.fall.preFallPos);
				if (respawnLoc == Vector2.zero)
				{
					respawnLoc = parent.lastCheckpoint;
				}
			}
			if (playerAlive)
			{
				parent.RequestTeleportMoveToLocation(respawnLoc);
				return;
			}
			parent.transform.position = respawnLoc;
			SpawnAllyPortal(parent.transform.position);
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.hurtBoxCollider.enabled = true;
			GameController.allies.Add(parent.gameObject);
		}

		public bool TakeFallDamage()
		{
			parent.health.showHitSpark = false;
			fallAtkInfo.damage = Mathf.FloorToInt(parent.FallDamage.CurrentValue);
			parent.health.TakeDamage(fallAtkInfo, null, critPreCalculated: true);
			parent.health.showHitSpark = true;
			PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Medium, parent.transform.position, parent.transform.position + Vector3.down * 2f, Health.playerHitSparkPSysOverride);
			return parent.health.healthStat.CurrentValue > 0f;
		}
	}

