			}
			if (Mathf.Abs(vectDiff.y) > maxVertDistFromPlayer)
			{
				trackOtherPlayerY = true;
			}
		}
		if (trackOtherPlayerX && Mathf.Abs(vectDiff.x) < maxHoriDistFromPlayer - resetDistDiff)
		{
			trackOtherPlayerX = false;
		}
		if (trackOtherPlayerY && Mathf.Abs(vectDiff.y) < maxVertDistFromPlayer - resetDistDiff)
		{
			trackOtherPlayerY = false;
		}
		if (trackOtherPlayerX || trackOtherPlayerY)
		{
			Movement movement = base.movement;
			Vector2 target = otherPlayer.transform.position;
			float magnitude = vectDiff.magnitude;
			movement.MoveToTarget(target, 0f, magnitude);
			return true;
		}
		return false;
	}

